'use strict';
// Sparse sufficient statistics. Integer endpoints are exact; original fractional Tmax sums remain float64.
const cache=new Map();let nodes,weights,lookup,palette,meta;
async function bytes(url,gzip=false){const r=await fetch(url);if(!r.ok)throw Error(`HTTP ${r.status}: ${url}`);if(gzip){if(!self.DecompressionStream)throw Error('This browser does not support recalculation. Use a recent browser version.');return new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();}return r.arrayBuffer();}
function readHistogram(buffer){const v=new DataView(buffer);if(v.getUint32(0,true)!==0x434C494D||v.getUint32(4,true)!==3)throw Error('Unknown data format');const n=v.getUint32(8,true),entries=v.getUint32(12,true),days=v.getUint32(16,true),years=v.getUint32(20,true),ne=v.getUint32(28,true),scale=v.getFloat64(32,true);let p=40;const offsets=new Uint32Array(buffer.slice(p,p+4*(n+1)));p+=4*(n+1);const bins=new Int8Array(buffer.slice(p,p+entries));p+=entries;const counts=new Uint16Array(buffer.slice(p,p+2*entries));p+=2*entries;const residual=new Int16Array(buffer.slice(p,p+2*entries));p+=2*entries;const exact=new Uint16Array(buffer.slice(p,p+2*entries));p+=2*entries;const noaa=new Float64Array(buffer.slice(p,p+8*(entries-ne)));if(p+8*(entries-ne)!==buffer.byteLength)throw Error('Incomplete data file');return {n,days,years,offsets,bins,counts,residual,noaa,ne,scale,exact};}
function histogram(period){if(!cache.has(period))cache.set(period,bytes(`assets/hist-${period}.gz`,true).then(b=>{const result=readHistogram(b);while(cache.size>2){const oldest=cache.keys().next().value;if(oldest===period)break;cache.delete(oldest);}return result;}).catch(e=>{cache.delete(period);throw e;}));return cache.get(period);}
async function initialize(){[meta,nodes,weights,lookup]=await Promise.all([fetch('assets/metadata.json').then(r=>r.json()),bytes('assets/dynamic-nodes.bin').then(b=>new Int32Array(b)),bytes('assets/dynamic-weights.bin').then(b=>new Float64Array(b)),bytes('assets/map-lookup.gz',true).then(b=>new Int32Array(b))]);palette=meta.palette.map(h=>[parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)]);}
const initialized=initialize();
function calculate(h,lower,upper){const ns=new Float64Array(h.n),nd=new Float64Array(h.n);for(let node=0;node<h.n;node++){let loss=0,count=0;for(let i=h.offsets[node];i<h.offsets[node+1];i++){const b=h.bins[i],c=h.counts[i],s=i<h.ne?(h.residual[i]+(h.bins[i]*100-50)*h.counts[i])*h.scale:h.noaa[i-h.ne];if(b<=lower)loss+=Math.max(0,lower*c-s);else if(b>upper)loss+=Math.max(0,s-upper*c);if(b>lower&&b<=upper)count+=c;if(b===lower)count+=h.exact[i];}ns[node]=100-loss/h.days;nd[node]=count/h.years;}const size=nodes.length/4,score=new Float64Array(size).fill(NaN),days=new Float64Array(size).fill(NaN);for(let i=0;i<size;i++){if(nodes[i*4]<0)continue;score[i]=0;days[i]=0;for(let j=0;j<4;j++){const k=i*4+j;if(weights[k]===0)continue;score[i]+=ns[nodes[k]]*weights[k];days[i]+=nd[nodes[k]]*weights[k];}}return {score,days};}
function raster(values,mode){const pixels=new Uint8ClampedArray(lookup.length*4);const min=mode==='days'?0:76,max=mode==='days'?150:98;for(let i=0;i<lookup.length;i++){const k=i*4,idx=lookup[i];let rgb=idx===-2?[239,239,239]:[255,255,255];if(idx>=0){const value=values[idx];if(Number.isFinite(value)){const t=Math.max(0,Math.min(1,(value-min)/(max-min)))*(palette.length-1),j=Math.min(palette.length-2,Math.floor(t)),f=t-j;rgb=palette[j].map((a,c)=>Math.round(a+(palette[j+1][c]-a)*f));}else rgb=[239,239,239];}pixels[k]=rgb[0];pixels[k+1]=rgb[1];pixels[k+2]=rgb[2];pixels[k+3]=255;}return pixels;}
self.onmessage=async({data})=>{try{await initialized;const h=await histogram(data.period);if(!Number.isInteger(data.lower)||!Number.isInteger(data.upper)||data.lower>=data.upper||data.lower< -30||data.upper>50)throw Error('Choose whole-degree limits between −30 and 50 °C, with the minimum below the maximum.');const result=calculate(h,data.lower,data.upper);const pixels=raster(result[data.mode],data.mode);self.postMessage({id:data.id,...result,pixels,width:meta.image_size[0],height:meta.image_size[1]},[result.score.buffer,result.days.buffer,pixels.buffer]);}catch(e){self.postMessage({id:data.id,error:e.message});}};
